import sympy

def gen_seq(a1, N):
    a = [a1]
    while len(a) < N:
        cur = a[-1]
        cand = cur + 1
        while True:
            if all(sympy.gcd(cand, x) > 1 for x in a):
                a.append(cand)
                break
            cand += 1
    return a

def find_min_period_tail(diffs, tail_frac=0.5, maxT=200):
    n = len(diffs)
    tailstart = int(n*(1-tail_frac))
    tail = diffs[tailstart:]
    m = len(tail)
    for T in range(1, maxT+1):
        if all(tail[i+T]==tail[i] for i in range(m-T)):
            return T, sum(tail[:T])
    return None, None

for a1 in [35, 77, 105, 15, 21]:
    seq = gen_seq(a1, 3000)
    diffs = [seq[i+1]-seq[i] for i in range(len(seq)-1)]
    T, L = find_min_period_tail(diffs, 0.5, 200)
    print(f"a1={a1}: T={T}, L={L}")
